scripts:
page.goto("https://www.sphinx-doc.org/en/master/");
page.getByRole("searchbox").fill("toctree");
page.getByRole("searchbox").press("Enter");
cu.click("toctree");
page.evaluate(() => ({url: location.href, title: document.title, h1: document.querySelector("h1")?.innerText, key_text: document.body.innerText.includes("toctree") ? "toctree" : "", values: [], answer: "toctree"}));

page.goto("https://www.sphinx-doc.org/en/master/");
cu.fill("Search", "toctree");
cu.press("Search", "Enter");
page.getByRole("link", {name: /toctree/i}).click();
page.evaluate(() => cu.claim({url: location.href, title: document.title, h1: document.querySelector("h1")?.innerText, key_text: document.body.innerText.includes("toctree") ? "toctree" : "", values: [], answer: document.querySelector("h1")?.innerText || ""}));

await page.goto('https://practice.expandtesting.com/form-validation');
await cu.fill('Contact name', 'Alex Example');
await cu.fill('Contact number', '012-3456789');
await cu.fill('Pick up date', '15 January 2030');
await cu.click('Card');
await cu.click('Submit');
page.evaluate(() => ({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: document.body.innerText.includes('Thank you') ? document.body.innerText.match(/[^.]*Thank you[^.]*\./)?.[0] || 'Thank you' : document.body.innerText.slice(-500), values: Array.from(document.querySelectorAll('input')).map(x => [x.name, x.value]), answer: document.body.innerText.match(/[^.]*Thank you[^.]*\./)?.[0] || ''}))

await page.getByLabel('Contact Name').fill('Alex Example');
await page.getByLabel('Contact number').fill('012-3456789');
await page.getByLabel('PickUp Date').fill('15 January 2030');
await page.getByLabel('Payment Method').selectOption({label:'card'});
await cu.click('Register');
page.evaluate(() => ({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: document.body.innerText.match(/[^\n]*[Tt]hank[^\n]*/)?.[0] || document.body.innerText.slice(-400), values: [], answer: document.body.innerText.match(/[^\n]*[Tt]hank[^\n]*/)?.[0] || ''}))
